import type { BlogPost } from './types';
import type { ResearchPost } from './types';

export const november11BlogPosts: readonly BlogPost[] = [{"slug":"set-up-a-privilege-safe-billing-narrative-review-for-litigation-matters","title":"Set up a privilege-safe billing narrative review for litigation matters","description":"A review routine that improves billing narratives without exposing privileged substance to the wrong reviewer.","category":"Time capture","readTime":"9 min read","thumbnail":"/thumbnails/november-11/set-up-a-privilege-safe-billing-narrative-review-for-litigation-matters.webp","internalService":"/services/time-entry-review-support","internalSibling":"/blog/build-a-client-guideline-intake-log-for-every-new-matter","source":{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Separate the narrative from the privileged substance","paragraphs":["Billing narratives describe the work well enough to support a fee without revealing the legal advice behind it. A reviewer needs the task, the matter phase, and the outcome that justifies the charge. That reviewer does not need the client's litigation strategy or the attorney's mental impressions. Start by defining which fields the billing reviewer may read and which fields stay inside the legal team.","A privilege review is not the same as a billing review, and one person should not silently do both. Give the billing reviewer a redacted export that keeps dates, timekeepers, and task categories while removing privileged content. Document the export rule in the matter file so a later reviewer can repeat it. The goal is a defensible fee record, not a broader distribution of sensitive material."]},{"heading":"Define what a reviewer may read","paragraphs":["Write a short access matrix that maps each role to the fields it can see. The billing coordinator can usually see time, task codes, and invoice amounts, while the responsible attorney sees the full narrative. A client-facing professional may see only the redacted description that will appear on the invoice. The matrix should name the systems where each view is enforced, not just the intent.","Test the matrix with a sample export before the first live review. Ask the reviewer to identify the task and the fee basis without opening a privileged document. If the redacted view is too thin to support the charge, add a neutral task description rather than restoring the privileged text. Record the decision so the next matter can reuse the same pattern."]},{"heading":"Build a redaction and escalation ladder","paragraphs":["Some narratives contain a single phrase that creates risk, such as a reference to advice on a settlement position. Teach reviewers to escalate that phrase to the responsible attorney instead of rewriting it themselves. The attorney can decide whether to replace the phrase, move the detail to a privileged file, or leave the entry out. The escalation should take minutes rather than days, or the prebill will wait.","Keep a log of escalations with the matter, the date, and the resolution. The log shows whether one timekeeper or one task type produces most of the sensitive wording. Use it to improve the entry guidance rather than to criticize the writer. A repeated escalation is a sign that the narrative standard needs a clearer example."]},{"heading":"Standardize narrative patterns without inventing facts","paragraphs":["Provide a small set of sentence patterns that describe common tasks, such as reviewed documents for a filing, conferred with the client on a schedule, or prepared a draft for partner review. These patterns help timekeepers write consistently, but they must never replace a fact the timekeeper cannot recall. A template that invents a meeting or a document is worse than a short honest entry. Each pattern should point to the evidence the reviewer can check, not to a conclusion the writer did not reach.","Review a sample of narratives each month against the source notes. Mark the entries that use a pattern without the supporting fact. Return those entries to the timekeeper for a correction before the prebill is released. The review should focus on accuracy, not on prose style."]},{"heading":"Review the prebill in a controlled workspace","paragraphs":["Move the prebill review into a workspace with version control and a clear owner. The reviewer should be able to leave a comment, request a change, and see who approved the final text. Do not circulate a spreadsheet by email, because versions will diverge and the privileged text will spread. A single workspace also gives the firm a record of who saw what.","Lock the narrative fields once the prebill is approved. Late edits should go through a short exception note that names the editor and the reason. This prevents a last-minute change from reintroducing sensitive wording after the privilege check. The lock is a control, not a sign of distrust."]},{"heading":"Train new reviewers on boundary cases","paragraphs":["Give every new reviewer the same five boundary examples before they touch a live prebill. Include a narrative that reveals a client's business plan, one that describes a settlement authority, and one that is simply too vague to support the fee. Ask the reviewer to explain what they would keep, redact, or escalate. Compare the answers with the approved rule.","Repeat the exercise after any change to the billing system or the client's outside counsel guidelines. A new export can expose fields that the old one hid. Update the training examples and the access matrix together so the guidance does not drift from the system. Keep a dated record of who completed the training."]},{"heading":"Measure narrative quality without reading content","paragraphs":["Count the entries returned for a missing fact, the entries escalated for privilege, and the entries cleared on the first pass. These measures show whether the review is working without requiring a manager to read every narrative. Report them by timekeeper and by task type, with enough context to avoid a simple ranking. Keep the measure stable so one month can be compared with the next without redefining the sample.","Track the time from prebill release to approval as a separate measure. A fast review that misses a sensitive phrase is not a success, and a slow review that catches everything may still be too expensive. Set a target range and inspect the exceptions. The measures should guide coaching, not punishment."]},{"heading":"Keep the record after the invoice is sent","paragraphs":["Retain the redacted export, the escalation log, and the approval record with the matter file. The firm may need them if a client questions the invoice or a regulator reviews the engagement. Store them under the same retention rule as the invoice, not in a personal folder. Name the records so a successor can find them without asking the original reviewer.","Review the retention rule once a year and after any change in the client's guidelines. Delete working copies that are no longer needed, but keep the approved record and the log. A clean retention practice protects the firm and makes the next review faster. It also shows the client that the billing process is controlled."]}],"faq":[{"q":"Who owns the narrative review?","a":"The responsible attorney owns the legal content and the privilege decision, while the billing coordinator owns the queue and the evidence. Name both owners in the matter record so a late question reaches the right person. The coordinator should never make a privilege call alone."},{"q":"What if the redacted entry is too vague to bill?","a":"Add a neutral task description that identifies the work without the strategy behind it. If the description still cannot support the fee, ask the timekeeper for a contemporaneous note. Do not restore privileged text just to make the invoice look complete."},{"q":"How often should the access matrix be tested?","a":"Test it at least once a year, after any billing system change, and when a new client guideline arrives. A short sample export is enough to confirm that each role sees the intended fields. Record the test date beside the matrix."}],"publishedAt":"2026-11-11"},{"slug":"build-a-client-guideline-intake-log-for-every-new-matter","title":"Build a client guideline intake log for every new matter","description":"A structured intake log that turns outside counsel guidelines into review questions before the first time entry is written.","category":"Billing guidelines","readTime":"9 min read","thumbnail":"/thumbnails/november-11/build-a-client-guideline-intake-log-for-every-new-matter.webp","internalService":"/services/matter-record-upkeep","internalSibling":"/blog/prepare-a-trust-to-operating-transfer-checklist-for-earned-fees","source":{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Open the log at matter intake","paragraphs":["Outside counsel guidelines arrive in many forms, including a PDF, a portal link, a short email, and a clause inside the engagement letter. The intake log gives each of those sources one home and one owner. Open the log when the matter is opened, not when the first invoice is rejected. A late log turns a preventable review into a dispute.","Record the client, the matter, the date the guideline arrived, and the person who confirmed it. Add a field for the version and the effective date, because clients update their rules. Link the source file rather than pasting an unverified summary. The log should answer where the rule came from and when it applied."]},{"heading":"Capture the guideline source and version","paragraphs":["Store the exact file or link that the client issued and label it with the date it was received. If the client sends a change by email, save the message with the file. Do not rely on a colleague's memory of a phone call. A versioned source is the only reliable way to resolve a later question about what the rule said.","Check whether the guideline has an effective date that differs from the date it was sent. A rule may apply to work performed after a stated date, not to the whole matter. Record that distinction in the log so the reviewer knows which entries to test. When the dates conflict, ask the client in writing."]},{"heading":"Translate the guideline into review questions","paragraphs":["Convert each requirement into a question the billing reviewer can answer with evidence. A rule about block billing becomes a question about whether each entry states a distinct task. A rule about travel becomes a question about the approved rate and the receipt. The question form makes the guideline usable during a prebill review.","Group the questions by the stage where they are checked, such as time entry, prebill, or submission. This prevents the reviewer from discovering a formatting rule after the invoice is final. Keep the list short enough to finish in one review pass. If a guideline has twenty requirements, mark the five that carry the most risk."]},{"heading":"Assign an owner for each requirement","paragraphs":["Give every review question a named owner and a backup. The timekeeper may own the narrative standard, the billing coordinator may own the rate check, and the responsible attorney may own a client-specific exception. An unowned requirement is usually the one that fails. Put the owner beside the question in the log.","Review the ownership map when a person changes role or leaves the firm. A guideline that depended on one coordinator will lapse during a transition. Update the name and test the new owner on a sample before the next invoice. Ownership should survive personnel changes."]},{"heading":"Flag conflicts with the engagement letter","paragraphs":["Compare the guideline with the engagement letter and the fee agreement. A guideline may cap travel, exclude a cost, or require a discount that the engagement letter does not mention. Record the conflict and the person who will resolve it. Do not assume the most recent document wins without confirmation.","Ask the client to confirm which document controls when the conflict affects money. Keep the written answer with the matter record. If the client will not confirm, escalate the issue before the work continues. A silent assumption can turn into a write-down at the end of the matter."]},{"heading":"Brief the timekeepers before the first entry","paragraphs":["Send a one-page brief to every timekeeper assigned to the matter. Include the narrative standard, the task codes, the travel rule, and the approval path. Ask each person to confirm they read it. A brief that arrives before the work starts is more useful than a correction after the invoice.","Use realistic examples from the client's own matters when they are available, and remove client identifiers. A sample entry that shows the expected level of detail is easier to follow than a policy paragraph. Keep the brief in the matter folder so it can be reused at the next prebill. Add a short question at the end that asks the timekeeper to name the one rule most likely to affect their entries."]},{"heading":"Audit the log at the first prebill","paragraphs":["Test the first prebill against every question in the log. Record which questions passed, which failed, and which could not be answered. The result shows whether the intake was complete and whether the brief reached the team. A first prebill that passes is a good sign, but it does not prove the log is complete.","Look for questions that were never relevant and questions that were missing. Remove the noise and add the gap. Update the template for the next matter, not just this one. The log should get shorter and sharper with use."]},{"heading":"Refresh the log when the client updates its rules","paragraphs":["Treat a guideline update as a new version, not an edit to the old record. Keep the prior version so an older invoice can still be explained. Notify the timekeepers and the billing reviewer on the same day. A change that reaches only one person will produce inconsistent entries.","Re-test one recent invoice against the new rule to see what would change. If the change affects open matters, decide whether to apply it to future work or to the whole matter. Record that decision and tell the client. The log is a living control, not a one-time intake form."]}],"faq":[{"q":"Where should the guideline log live?","a":"Keep it with the matter record in the system the billing team already uses. Link the source file and name the owner so the log is not a separate document that nobody updates. A shared drive folder is acceptable only if access is controlled."},{"q":"What if the client has no written guidelines?","a":"Record that no written guideline was provided and note the date you asked. Apply the firm's standard billing rules and confirm any special term in writing. The absence of a guideline should be documented, not assumed."},{"q":"Who resolves a conflict with the engagement letter?","a":"The responsible attorney and the client resolve it, with the billing manager documenting the answer. The billing coordinator should not choose between two client documents alone. Keep the written confirmation with the matter record."}],"publishedAt":"2026-11-11"},{"slug":"prepare-a-trust-to-operating-transfer-checklist-for-earned-fees","title":"Prepare a trust-to-operating transfer checklist for earned fees","description":"A step-by-step transfer routine that keeps earned fees, client notices, and trust reconciliations in agreement.","category":"Trust accounting","readTime":"9 min read","thumbnail":"/thumbnails/november-11/prepare-a-trust-to-operating-transfer-checklist-for-earned-fees.webp","internalService":"/services/billing-reporting-support","internalSibling":"/blog/design-a-billing-coordinator-calendar-for-the-monthly-close","source":{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Confirm the fee is earned before any transfer","paragraphs":["A trust account holds client money until the firm has earned the fee or the client has authorized the payment. Start the checklist by matching the invoice to the work that was actually performed. Confirm that the amount is billed, approved, and not subject to a client dispute. A transfer made before the fee is earned creates a compliance problem that is hard to undo.","Check the engagement letter for the firm's authority to withdraw earned fees. Some agreements require a written invoice and a waiting period before the transfer. Others require the client's signed approval for each withdrawal. Record the authority you relied on beside the transfer entry. The record should let a later reviewer reach the same conclusion."]},{"heading":"Match the invoice to the trust ledger","paragraphs":["Compare the invoice number, the client, the matter, and the amount with the trust ledger. Look for prior partial payments and for any credit that was already applied. Do not transfer an amount that exceeds the remaining trust balance. A small mismatch at this stage becomes a reconciliation problem at the end of the month.","Print or save the ledger view that shows the balance before the transfer. Attach it to the checklist so the reviewer can see the starting point. If the ledger and the billing system disagree, stop and resolve the difference before moving money. The reconciliation should not be done after the transfer."]},{"heading":"Prepare the client notice and the authorization","paragraphs":["Draft a short notice that states the invoice amount, the transfer date, and the remaining trust balance. Attach the invoice and the ledger summary. If the engagement requires client approval, send the notice before the transfer and wait for the response. Keep the sent message with the checklist.","Use plain language and avoid legal conclusions about the client's obligation. The notice should help the client understand what happened, not pressure them. If the client objects, pause the transfer and route the issue to the responsible attorney. A documented objection is a signal to review the invoice, not to proceed."]},{"heading":"Record the transfer in both ledgers","paragraphs":["Enter the transfer in the trust ledger and in the operating ledger on the same day. Use the same reference number in both entries so a reconciliation can match them. Record the invoice number, the amount, and the person who approved the transfer. A one-sided entry is the most common cause of a trust reconciliation break.","Reconcile the trust balance immediately after the entry. Confirm that the client's ledger and the pooled bank balance still agree. If the firm uses a journal, post the transfer with a clear description. The audit trail should show the movement without requiring an explanation from the bookkeeper."]},{"heading":"Handle partial payments and retainers","paragraphs":["A client may pay part of an invoice or replenish a retainer while an invoice is open. Apply the payment to the oldest approved invoice unless the client directs otherwise in writing. Record the instruction and the remaining balance. Do not let a partial payment create an unexplained credit on the account.","For a replenishment, confirm the amount requested and the trust balance before the client sends funds. Update the retainer tracking sheet and the matter record. If the replenishment is late, follow the firm's written policy rather than making an ad hoc call. The same rule should apply to every client in the same situation. Keep the client's written direction with the payment record so a later reviewer can see why the balance changed."]},{"heading":"Reconcile the trust balance after the transfer","paragraphs":["Complete the three-way reconciliation after any transfer that changes the client ledger. Compare the client ledger, the trust journal, and the bank statement. Investigate any difference the same day rather than carrying it to month end. A small unexplained difference can hide a larger error. A difference that is found and explained on the same day is a minor correction rather than a compliance issue.","Have a second person review the reconciliation when the firm's policy requires it. Record the reviewer's name and the date. Keep the reconciliation with the bank statement and the transfer checklist. The record should be easy to retrieve during an audit or a bar inquiry."]},{"heading":"Keep the audit trail for the required period","paragraphs":["Store the invoice, the client notice, the authorization, the ledger entries, and the reconciliation in one folder. Follow the retention period required by the firm's jurisdiction and the engagement. Do not rely on the bank's records alone, because they do not show the client-level allocation. A complete file answers questions years later.","Protect the folder with access limited to the people who need it. Trust records contain client financial information and sometimes sensitive matter details. Use the same retention rule for electronic and paper copies. When the retention period ends, dispose of the records according to the firm's policy."]},{"heading":"Review the routine with the bookkeeper and the attorney","paragraphs":["Walk through the checklist with the bookkeeper and the responsible attorney once a quarter. Ask where the process stalled and which step caused the most rework. A transfer that waits for an approval is a different problem from a transfer that was recorded twice. Fix the step, not just the individual error.","Update the checklist when the firm changes banks, software, or engagement terms. Test the new version on one transfer before applying it to every client. Keep the old version for the records that were already completed. The routine should be stable enough to audit and flexible enough to improve."]}],"faq":[{"q":"Can the firm transfer fees without sending a notice?","a":"Only if the engagement letter and the jurisdiction allow it. Many firms still send a notice because it reduces disputes and creates a record. Check the written authority before changing the routine."},{"q":"What if the client disputes part of the invoice?","a":"Pause the disputed portion and transfer only the undisputed amount if the rules allow it. Route the dispute to the responsible attorney and document the client's objection. Do not use the trust balance to settle a disagreement without written authority."},{"q":"Who should review the reconciliation?","a":"A person who did not prepare the transfer, when the firm's policy requires independent review. The reviewer should sign and date the reconciliation. Small firms may use the responsible attorney or an outside bookkeeper."}],"publishedAt":"2026-11-11"},{"slug":"design-a-billing-coordinator-calendar-for-the-monthly-close","title":"Design a billing coordinator calendar for the monthly close","description":"A close calendar that names cutoffs, owners, review windows, and exception paths before the first deadline slips.","category":"Billing operations","readTime":"9 min read","thumbnail":"/thumbnails/november-11/design-a-billing-coordinator-calendar-for-the-monthly-close.webp","internalService":"/services/prebill-preparation","internalSibling":"/blog/audit-a-timekeeper-s-block-billing-pattern-before-the-client-does","source":{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},"sections":[{"heading":"Map the close from the last time entry to the final report","paragraphs":["Start the calendar with the last time entry that must be captured and end it with the report the client receives. List every handoff in between, including the prebill review, the rate check, the cost review, the approval, and the submission. A calendar built from the deadline backward is easier to defend than a list of tasks with no dates. Show the map on one page so a new team member can see where their work fits. Name the person who will publish the calendar and the person who can approve a date change.","Mark the tasks that must finish before another task can start. The prebill cannot be released until the time entries are locked, and the invoice cannot be submitted until the approval is recorded. Those dependencies determine the real critical path. Share the map with the team so everyone sees the same sequence."]},{"heading":"Set the cutoffs and the freeze points","paragraphs":["Publish the time-entry cutoff, the cost-entry cutoff, and the prebill freeze date. State the time zone and the system of record for each cutoff. A cutoff that is described only as end of day invites a late entry and a rebuild. The calendar should show the exact date and time.","Define what happens to an entry that arrives after the cutoff. It may move to the next cycle, or it may require an exception approval. Record the rule and the approver. A clear exception path prevents a late entry from becoming a quiet edit to a released invoice. A cutoff that moves without a record makes the close impossible to compare with the prior month."]},{"heading":"Assign owners for each handoff","paragraphs":["Name one owner for each task and one backup. The owner is accountable for the handoff, not for every detail inside it. A task with two owners usually has none. Put the names and the contact method in the calendar rather than in a separate directory.","Review the owners when someone is on leave or changes role. A close calendar that depends on one person is fragile. Test the backup on a real handoff before the busy period. The test should include the system access, not just the intention to help. A backup who cannot open the prebill is not a real backup."]},{"heading":"Build the exception queue before the deadline","paragraphs":["Open the exception queue at the start of the close, not after the first problem appears. The queue should capture missing approvals, rate conflicts, cost receipts, and client questions. Give each item an owner, a due date, and a status. A visible queue keeps exceptions from being handled in private email.","Review the queue at a fixed time each day during the close. Close the items that are resolved and escalate the ones that are stuck. Do not let the queue become a second inbox that nobody reads. The daily review is the control that makes the queue useful."]},{"heading":"Schedule the review and approval windows","paragraphs":["Reserve a specific window for the reviewer and a separate window for the approver. Do not assume that both can happen on the final day. A review window that is too short encourages a superficial check. The calendar should show the start and end of each window.","Send the prebill to the reviewer at the start of the window with the exception queue attached. Ask for a decision by the end of the window. If the reviewer is late, escalate to the owner rather than silently extending the deadline. The next close will inherit the standard you set."]},{"heading":"Prepare the client-facing status note","paragraphs":["Draft a short status note before the close begins. State the expected invoice date, the contact for questions, and any known exception. The note gives the client a chance to raise an issue before the invoice is final. It also reduces the number of questions that arrive after submission.","Update the note if the date changes or a material exception appears. Keep the language factual and avoid promising a result you cannot control. Store the note with the close record so the client communication is part of the audit trail. A consistent note builds trust across cycles."]},{"heading":"Run a short post-close review","paragraphs":["Hold a thirty-minute review after the close with the owners of the main handoffs. Ask what arrived late, what was reworked, and what the client questioned. Record one change for the next cycle and one thing to keep. A long retrospective with no decision is not useful.","Compare the actual dates with the calendar and mark the tasks that slipped. Look for a pattern rather than a single bad day. If the same handoff is late every month, the calendar is wrong or the staffing is short. Fix the cause before adding another reminder. The post-close review should produce one owner and one due date for each change."]},{"heading":"Adjust the calendar for busy seasons","paragraphs":["Build a busy-season version of the calendar with earlier cutoffs and more review capacity. A calendar that works in a quiet month may fail when several clients close at once. Identify the weeks with the highest volume and protect the review windows. The adjustment should be planned, not improvised.","Review the busy-season version after it runs and keep the changes that helped. Remove the steps that added work without reducing risk. Share the revised calendar with the whole team before the next peak. A calendar is a living schedule, not a fixed policy."]}],"faq":[{"q":"How far ahead should the close calendar be published?","a":"Publish it at least one month before the close, and earlier for a busy season. The team needs time to plan around the cutoffs and the review windows. A late calendar turns every handoff into an exception."},{"q":"What belongs in the exception queue?","a":"Any item that blocks a clean invoice, such as a missing approval, a rate conflict, an unsupported cost, or an open client question. Give each item an owner and a due date. The queue should not include routine work that is already on schedule."},{"q":"Should the client see the close calendar?","a":"Share the dates that affect the client, such as the invoice date and the question window. Keep internal review steps private. A short client-facing note is usually enough."}],"publishedAt":"2026-11-11"},{"slug":"audit-a-timekeeper-s-block-billing-pattern-before-the-client-does","title":"Audit a timekeeper's block-billing pattern before the client does","description":"A practical review that finds reconstructed or over-broad time entries before they reach a client guideline dispute.","category":"Time capture","readTime":"9 min read","thumbnail":"/thumbnails/november-11/audit-a-timekeeper-s-block-billing-pattern-before-the-client-does.webp","internalService":"/services/time-entry-review-support","internalSibling":"/blog/create-a-write-down-approval-memo-that-survives-a-client-audit","source":{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},"sections":[{"heading":"Define what counts as a block entry","paragraphs":["A block entry combines several tasks into one time record without separating the time spent on each. Some blocks are legitimate, such as a hearing that covers several issues in one continuous session. Others hide a day of work behind a vague description. Define the threshold the firm will review, such as any entry over four hours or any entry with more than one task verb.","Write the definition into the review guide with two clear examples. Include a boundary case, such as a deposition preparation that spans several documents but is one continuous task. The reviewer needs a consistent rule before looking at individual timekeepers. A definition that changes per matter will not produce a fair result."]},{"heading":"Pull a sample across timekeepers and matters","paragraphs":["Sample across timekeepers, practice groups, and matter types rather than focusing on one person. Include entries that were already billed without a client question, because the absence of a complaint is not proof of quality. Draw the sample before reading the narratives so the selection is not biased toward the suspicious. Record the sampling rule and the population so another reviewer can repeat the selection.","Stratify the sample by entry length and by task type. Long entries and entries with several verbs are more likely to need a closer look. Report the number of entries and the number of timekeepers behind each result. A pattern based on one person is a coaching issue, not a firm-wide finding."]},{"heading":"Compare the block to the underlying notes","paragraphs":["Ask for the contemporaneous notes, drafts, and calendar entries that support the block. Compare the time recorded with the work product and the meeting times. A block that claims eight hours of document review should have a produced document or a clear work trail. If the note is missing, record the gap rather than assuming the worst.","Check whether the block combines work from different days or different matters. A single entry that spans a weekend may be a reconstruction. Look for language that describes the outcome rather than the activity. The comparison should be factual and repeatable by a second reviewer."]},{"heading":"Look for patterns that suggest reconstruction","paragraphs":["Repeated round numbers, identical daily totals, and entries written in one sitting can suggest that time was reconstructed later. These signs are not proof, and a timekeeper may have a legitimate explanation. Use them to decide where to look next, not to reach a conclusion. The review should distinguish a pattern from an accusation.","Compare the entry dates with the system audit trail when the billing software keeps one. A batch of entries created on the same day for work performed weeks earlier deserves a question. Ask for the source record before drawing a conclusion. Document the answer with the sample."]},{"heading":"Ask for a contemporaneous explanation","paragraphs":["Send a short request that names the entry and asks for the supporting record. Avoid a general request for an explanation, because it invites a narrative written after the fact. Ask for the calendar item, the draft, or the note that existed at the time. Set a reasonable deadline and copy the supervising attorney.","Record the response and whether it changed the entry. If the explanation is credible, close the item and note the evidence. If it is not, escalate to the billing manager and the responsible attorney. Do not negotiate the entry in a private message that leaves no record."]},{"heading":"Correct the entries before the prebill","paragraphs":["Correct the narrative, split the block, or remove the unsupported time before the prebill is released. Record the change and the reason in the matter file. A correction made after the client sees the invoice is harder to explain and may require a credit. The earlier the fix, the more options the firm has.","Recheck the corrected entry against the source record. Confirm that the new narrative still supports the fee and that the time total is accurate. If the correction changes the invoice amount, update the client-facing summary. The correction should leave a clear trail, not erase the original record."]},{"heading":"Report the pattern without ranking people","paragraphs":["Report the findings by entry type, matter, and timekeeper group rather than as a public ranking. The purpose is to improve the record, not to shame individuals. Share the aggregate pattern with the billing manager and the practice group leader. Discuss individual cases privately with the supervising attorney.","Include the entries that were well documented so the report shows the full picture. A report that lists only failures can discourage the behavior you want. Note the examples that show a clear task, a matching source, and a reasonable time. Use them in the next training session."]},{"heading":"Change the entry guidance and recheck","paragraphs":["Update the entry guidance with the examples from the review. Add a prompt for the source record and a short list of task verbs. Ask the timekeepers to use the new guidance on the next cycle. A guidance change is more durable than a one-time correction.","Recheck a small sample after the change to see whether the pattern improved. Compare the same measures and the same sample method. If nothing changed, the problem may be workload or staffing rather than guidance. Report that possibility honestly and involve the practice group leader. A short follow-up sample is enough to show whether the guidance reached the people who write the entries."]}],"faq":[{"q":"Is block billing always improper?","a":"No. A continuous task that genuinely spans several activities can be described in one entry. The problem is an entry that hides separate tasks or cannot be supported by a source record. Review the substance, not the format alone."},{"q":"Should the client be told about the audit?","a":"Tell the client only if the review changes an invoice or reveals a guideline issue that affects them. The internal audit is a quality control process. Share the corrected record and a brief explanation when a change is needed."},{"q":"What if the timekeeper refuses to provide notes?","a":"Escalate to the supervising attorney and the billing manager. The firm cannot support the entry without evidence. Document the request and the response before deciding whether to remove the time."}],"publishedAt":"2026-11-11"},{"slug":"create-a-write-down-approval-memo-that-survives-a-client-audit","title":"Create a write-down approval memo that survives a client audit","description":"A memo template that ties every write-down to an authority limit, a reason, and the evidence a client or auditor will ask for.","category":"Write-offs","readTime":"9 min read","thumbnail":"/thumbnails/november-11/create-a-write-down-approval-memo-that-survives-a-client-audit.webp","internalService":"/services/billing-reporting-support","internalSibling":"/blog/set-up-shared-inbox-triage-for-client-invoice-questions","source":{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},"sections":[{"heading":"State the adjustment and the reason","paragraphs":["Open the memo with the invoice, the matter, the client, and the exact amount being reduced. State the reason in one sentence that a reader can test against the record. A reason such as client relationship is too broad, while a reason such as duplicate cost line is specific and reviewable. The memo should not require the reader to reconstruct the story.","Separate the amount that is being written down from the amount that is being written off. A write-down reduces a billed amount, while a write-off removes time that was never billed. Use the terms consistently and show the effect on the invoice total. A clear definition prevents a later disagreement about what was approved. A memo written after the client complains may describe a decision that was never made."]},{"heading":"Name the authority and the limit","paragraphs":["Cite the policy or delegation that allows the approver to make the adjustment. State the limit and confirm that the amount is inside it. If the amount exceeds the limit, name the person who approved the exception. An approval without a visible authority is difficult to defend in an audit.","Attach the current delegation schedule or link to it. Do not rely on a title alone, because authority can change without the title changing. If the approver is new, confirm the delegation in writing. The memo should show that the approver had the authority on the date of the decision. Keep the delegation schedule dated so the authority can be tested at that point in time."]},{"heading":"Attach the evidence the client will expect","paragraphs":["Attach the invoice line, the time or cost record, and the client correspondence that explains the issue. If the client requested the adjustment, include the request. If the firm found an error, include the correction. The evidence should let a reviewer reach the same conclusion without interviewing the approver.","Remove unrelated client material before attaching the evidence. The memo may be shared with the client or an auditor, so it should not expose another matter. Mark privileged material and keep it in a separate restricted file. The approval record should be complete and safe to disclose. A short index at the front of the evidence package saves the reviewer from opening every attachment."]},{"heading":"Separate a courtesy adjustment from an error correction","paragraphs":["A courtesy adjustment is a business decision to preserve a relationship, while an error correction fixes a mistake in the invoice. The two need different evidence and different reporting. A courtesy adjustment should state the business reason and the person who approved it. An error correction should point to the incorrect entry and the corrected amount.","Do not label an error as a courtesy to avoid a quality review. The pattern of errors is important management information. Likewise, do not label a courtesy as an error to avoid a business discussion. Clear categories make the write-down report useful. The category also changes who is accountable for the fix and what the client is told."]},{"heading":"Describe the effect on the invoice and the matter","paragraphs":["Show the original invoice total, the adjustment, and the revised total. State whether a credit memo or a new invoice will be issued. If the adjustment affects a trust transfer or a payment already received, explain how the balance will be handled. The finance team should not have to infer the accounting treatment.","Note whether the adjustment changes the matter budget or the client's accrual. A large write-down can affect the next estimate and the client's internal reporting. Tell the client relationship owner so the next conversation is informed. The memo is a financial record, not just an approval note."]},{"heading":"Route the memo through the approval chain","paragraphs":["Send the memo to the first approver with the evidence attached and a clear decision requested. Do not send it to several people at once, because no one will own the decision. Record each approval with a name and a date. If the memo is rejected, record the reason and the next step.","Use the same route for every adjustment above the threshold so the process is predictable. A separate informal route for a senior partner undermines the control. If an urgent adjustment needs a faster path, document the urgency and the person who authorized it. The exception should still leave a record."]},{"heading":"Record the client conversation","paragraphs":["Write a short note after the client conversation that states what was discussed and what was agreed. Include the date, the participants, and the amount. If the client asked for the adjustment, quote the request. If the firm proposed it, state the client's response. The note should be factual and free of speculation.","Send the client a written confirmation of the adjustment and the revised invoice. Ask the client to confirm receipt if the amount is material. Keep the confirmation with the memo. A verbal agreement that is never confirmed can be reopened months later."]},{"heading":"Review the memo after the invoice closes","paragraphs":["Check that the adjustment was posted correctly and that the invoice reflects the approved amount. Compare the memo with the accounting entry and the client confirmation. A memo that was approved but never posted is an open control gap. Close the loop before the file is archived.","Review a sample of memos each quarter for completeness and consistency. Look for missing authority, vague reasons, and repeated causes. Report the pattern to the billing manager and the finance owner. The review should improve the template and the approval habit."]}],"faq":[{"q":"Who should approve a write-down?","a":"The person named in the firm's delegation schedule for that amount and type of adjustment. Confirm the limit and the date of the authority. A larger adjustment should go to the next level rather than being split to fit a limit."},{"q":"Does every write-down need a memo?","a":"Use the memo for adjustments above the firm's threshold and for any adjustment that a client may question. Small routine corrections can use a shorter log if the policy allows it. The key is a consistent record."},{"q":"Can the memo be shared with the client?","a":"Yes, if it is written for that purpose and contains no unrelated or privileged material. Keep a separate internal version when the discussion includes sensitive matter details. The client-facing version should still show the reason and the amount."}],"publishedAt":"2026-11-11"},{"slug":"set-up-shared-inbox-triage-for-client-invoice-questions","title":"Set up shared-inbox triage for client invoice questions","description":"A triage routine that routes invoice questions to the right owner, protects sensitive information, and closes the loop.","category":"Invoice follow-up","readTime":"9 min read","thumbnail":"/thumbnails/november-11/set-up-shared-inbox-triage-for-client-invoice-questions.webp","internalService":"/services/invoice-follow-up","internalSibling":"/blog/build-a-quarterly-accrual-packet-corporate-clients-can-reconcile","source":{"label":"NIST Cybersecurity Framework 2.0","url":"https://www.nist.gov/cyberframework"},"sections":[{"heading":"Separate invoice questions from other client mail","paragraphs":["A shared inbox mixes invoice questions with scheduling, document requests, and matter updates. Create a label or folder for billing questions and route them to a named queue. The billing team should not have to search the whole inbox to find a question about a line item. A clear route also reduces the chance that a question is answered by the wrong person.","Tell clients which address to use for billing questions and include it on the invoice. If a question arrives in another channel, move it to the queue and acknowledge it. Do not let a private message become the only record of a fee dispute. The queue is the system of record for the response."]},{"heading":"Set the first-response standard","paragraphs":["Acknowledge every invoice question within one business day, even when the answer will take longer. The acknowledgment should name the owner and the expected response time. A quick acknowledgment prevents the client from escalating while the team researches. It also creates a timestamp for the response measure. The acknowledgment should not speculate about the outcome before the owner has read the record.","Define what counts as a complete first response. For a simple question, it may be the answer. For a complex dispute, it may be an acknowledgment plus a request for the specific invoice lines. Do not promise a resolution date you cannot meet. The standard should be realistic and consistently applied."]},{"heading":"Assign each message a category and an owner","paragraphs":["Use a short category list such as time entry, rate, cost, format, payment, or other. Assign the owner by category and matter, not by whoever happens to see the message first. The owner is responsible for the next action and the final response. Record the assignment in the queue.","Review unassigned messages at the end of each day. A message without an owner is the one that will be forgotten. If the category is unclear, assign it to the billing coordinator for triage. The coordinator can route it after reading the question. A message that crosses two categories should be split so each owner can act without waiting for the other."]},{"heading":"Protect sensitive information in the shared queue","paragraphs":["Limit access to the billing inbox to the people who need it. Do not forward a client message to a personal address or a chat channel. If a screenshot is needed, redact unrelated client information before sharing it. The queue should follow the firm's data security policy, not a convenience rule.","Check the recipient before sending a reply, especially when the message contains another client's name or a privileged detail. Use a standard signature and avoid including internal notes in the client thread. If a message was sent in error, follow the firm's incident process. A quick report is better than a quiet deletion."]},{"heading":"Build a reply library with approved language","paragraphs":["Write short approved replies for common questions, such as how to read a time entry or how to request a copy of a receipt. Keep the language factual and avoid admissions or legal conclusions. Have the billing manager and the responsible attorney approve the templates. The library saves time without inventing an answer.","Leave a blank for the specific facts and require the owner to fill it in. Do not let a template answer a question it does not fit. Review the library each quarter and remove replies that generate follow-up questions. The templates should improve with use."]},{"heading":"Escalate disputes on a defined trigger","paragraphs":["Define when a question becomes a dispute, such as a written objection to a fee, a threat to withhold payment, or a request for a credit above a set amount. Route those messages to the responsible attorney and the billing manager immediately. Do not let the coordinator negotiate a material reduction alone. Give the escalation a deadline and a named backup so the question does not sit while the client waits.","Give the escalation path a time limit and a backup. If the attorney does not respond within the limit, the manager decides the next step. Record the escalation and the outcome in the queue. A dispute that stays in the inbox too long becomes harder to resolve."]},{"heading":"Track closure and repeat questions","paragraphs":["Close a message only when the client confirms the answer or the firm records a final adjustment. Track the time to first response and the time to closure. Report the categories that generate the most questions. A repeat question is a signal that the invoice or the explanation needs work.","Review closed messages each week for unresolved threads and missing confirmations. Reopen a message if the client replies with a new question. Do not merge unrelated questions into one thread, because the record becomes hard to follow. Clean closure makes the next review easier."]},{"heading":"Review the queue every week","paragraphs":["Hold a short weekly review of volume, response time, open disputes, and repeat categories. Ask which question took the longest and why. Identify one change to the invoice template, the reply library, or the routing rule. A weekly habit prevents a backlog from forming. Keep the review under thirty minutes so it stays on the calendar.","Share the aggregate results with the billing manager and the client relationship owner. Do not rank individual responders in a public report. Use the review to improve the process and to recognize good handling. The queue should be a learning tool, not a surveillance record."]}],"faq":[{"q":"Should the shared inbox be used for payment instructions?","a":"Keep payment instructions in the firm's approved billing system or portal. A shared inbox can receive the question, but it should not store bank details. Route payment changes to finance and verify them by a second channel."},{"q":"How quickly should a dispute be escalated?","a":"Escalate as soon as the message meets the written trigger, ideally the same business day. A delay can lead the client to withhold payment or involve another contact. Document the escalation time."},{"q":"Can templates be used for every reply?","a":"Use templates for routine questions and always add the specific facts. A template that does not fit the question can create a new problem. Review the templates when the same follow-up appears repeatedly."}],"publishedAt":"2026-11-11"},{"slug":"build-a-quarterly-accrual-packet-corporate-clients-can-reconcile","title":"Build a quarterly accrual packet corporate clients can reconcile","description":"A repeatable packet that explains unbilled time, cost estimates, and prior-quarter variances before the client closes its books.","category":"Accruals","readTime":"9 min read","thumbnail":"/thumbnails/november-11/build-a-quarterly-accrual-packet-corporate-clients-can-reconcile.webp","internalService":"/services/billing-reporting-support","internalSibling":"/blog/set-up-a-privilege-safe-billing-narrative-review-for-litigation-matters","source":{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},"sections":[{"heading":"Agree the accrual definition with the client","paragraphs":["An accrual packet is only useful if the client and the firm mean the same thing by accrued fees. Confirm whether the number includes unbilled time, estimated costs, taxes, and known adjustments. Ask how the client records the amount and when it needs the packet. Write the definition into the engagement record.","Different clients use different cutoffs and materiality thresholds. A client may want a single number, while another wants a matter-level detail file. Agree the format before the first quarter so the packet does not need a rebuild. The definition should be stable across quarters. A definition that changes between quarters makes the prior reconciliation meaningless."]},{"heading":"Collect unbilled time and costs at the cutoff","paragraphs":["Lock the time and cost entries at the agreed cutoff and export the unbilled detail. Include the matter, the timekeeper, the hours, the rate, and the amount. Check for entries that were posted after the cutoff but before the export. A clean cutoff is the foundation of a credible estimate.","Separate time that is ready to bill from time that is still under review. The client should not see an estimate that includes work the firm has not approved. Mark the held items and explain why they are excluded. The packet should show the basis for the number, not just the total. The client's finance team should be able to tie the packet to its own ledger without a separate call."]},{"heading":"Apply the client's rate and guideline rules","paragraphs":["Use the approved rate card and the client's billing guidelines when estimating the amount. Apply any cap, discount, or fixed fee that is already agreed. Do not estimate at a rate the client has not approved, even if the firm expects an increase. The packet should reflect the current written terms.","Check the matter record for a special rate or a blended fee. A matter-level exception can change the estimate significantly. Record the rule you applied beside the calculation. If the rule is unclear, ask the client before the packet is sent. A rate that is still under negotiation should be flagged rather than assumed."]},{"heading":"Show the basis for each estimate","paragraphs":["Give the client a short explanation of how each material estimate was built. For time, state the hours and the rate. For costs, state the vendor and the expected amount. For a fixed fee, state the milestone and the percentage complete. A number without a basis invites a question and a delay.","Keep the detailed calculation in an appendix and the summary in the main packet. The client's finance team may need the detail, while the relationship owner needs the total. Use the same format each quarter so the client can compare. A consistent packet is easier to reconcile. Ask the client to identify the person who will reconcile the packet on their side."]},{"heading":"Reconcile the prior quarter's accrual","paragraphs":["Compare the prior quarter's estimate with the invoices that followed. Show the difference and explain the main causes. A variance caused by timing is different from a variance caused by a rate change or a write-down. The client needs to understand which one occurred.","Carry the prior-quarter variance into the current packet as a note. If the estimate was consistently high or low, adjust the method rather than repeating the error. Discuss the pattern with the client relationship owner. The reconciliation is the part of the packet that builds credibility. Keep the note short enough for the client to read before the close meeting."]},{"heading":"Explain material variances","paragraphs":["Set a materiality threshold with the client, such as a percentage of the total or a fixed amount. Explain every variance above the threshold in plain language. Include the matter, the reason, and the expected effect on the next invoice. Do not bury a large variance in a footnote.","Distinguish a one-time event from a trend. A single expert fee is different from a matter that is consistently over budget. If the trend is likely to continue, tell the client before the next quarter. A timely warning is more useful than a surprise."]},{"heading":"Deliver the packet on the client's schedule","paragraphs":["Confirm the client's close calendar and deliver the packet before the deadline. Send it to the named contact and copy the relationship owner. Use a secure channel and protect the file with the firm's standard controls. A late packet can delay the client's close even when the number is accurate.","Ask for confirmation that the packet was received and accepted. If the client has a question, answer it within the agreed response time. Keep the sent packet and the confirmation with the matter record. The delivery record is part of the accrual audit trail. If the client cannot confirm receipt, follow up before the close date."]},{"heading":"Keep a version for the next cycle","paragraphs":["Save the final packet, the underlying detail, and the client's response in one folder. Note any change to the definition or the format. The next quarter should start from the same structure rather than a blank page. A versioned packet reduces the time spent rebuilding.","Review the packet after the invoices are issued to see how close the estimate was. Record the lesson in a short note for the next cycle. Share the note with the billing and relationship teams. The packet improves when the firm treats it as a process rather than a one-time deliverable."]}],"faq":[{"q":"What should an accrual packet include?","a":"Include the total estimate, the matter-level breakdown, the cutoff date, the rate basis, and the prior-quarter reconciliation. Add a short note for each material variance. Keep the detailed calculation in an appendix."},{"q":"How do we handle unbilled time that is still under review?","a":"Exclude it from the estimate or show it separately as held time. Explain why it is held and when it may be billed. Do not include work the firm has not approved as if it were certain."},{"q":"Should the packet match the invoice exactly?","a":"No. An accrual is an estimate made before the invoice, so some difference is expected. The goal is a documented, reasonable basis and a clear explanation of material changes. Reconcile the difference in the next packet."}],"publishedAt":"2026-11-11"}];

export const november11ResearchPosts: readonly ResearchPost[] = [{"slug":"how-often-do-billing-narratives-omit-the-business-purpose-of-the-task","title":"How often do billing narratives omit the business purpose of the task?","summary":"A narrative audit that tests whether a billed entry explains why the work was necessary, not just what activity occurred.","cluster":"Narrative quality","finding":"A large share of billing disputes starts with an entry that names an activity but never explains why the work was needed at that point in the matter.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how often a billed time narrative omits the business purpose of the task. The unit is a billed time line, and the measure is whether a reader can identify why the task was necessary and how it advanced the matter. The study covers narratives on invoices issued during the period, not the quality of the legal work. It does not evaluate whether the time spent was reasonable.","Scope the study to matters with at least one narrative entry above the firm's minimum billing threshold. Include invoices that were paid, adjusted, and still open so the denominator reflects the full workload. Exclude fixed-fee lines and cost-only lines, and record the number excluded. State the billing system, the narrative standard, and the owner of the analysis."]},{"heading":"Defining the event","paragraphs":["Define a purpose gap as a narrative that describes an activity but not the reason it was needed at that stage. Reviewed documents is an activity, while reviewed the production to identify documents responsive to the court order states a purpose. A short entry can still have a purpose, and a long entry can still lack one. Write two examples and one boundary case before coding.","Distinguish a purpose gap from a vague verb and from a missing narrative. A vague verb may still be clear in context, while a missing narrative is a blank field with a separate code. Keep the categories separate because the repair differs. Code the primary issue and note any secondary issue."]},{"heading":"Population and denominator","paragraphs":["The population is every narrative time line on an included invoice. Report the number of invoices, the number of lines, the number excluded, and the number in the final sample. Count lines rather than invoices, because one invoice can contain entries from several timekeepers. If a line was revised after the invoice, use the version that the client received.","Report the purpose gap rate by line and by billed value. A small number of high-value lines can carry most of the client exposure, so the value measure matters. Keep both measures in the report. The value measure should use the billed amount, not a notional rate."]},{"heading":"Evidence sources","paragraphs":["Use the invoice narrative, the contemporaneous time note, the task code, and the client guideline as the primary evidence. Compare the narrative with the note and record the date each was observed. If the note is missing, mark the line as incomplete rather than inferring the purpose from the matter name. The evidence log should let a second reviewer repeat the match.","Rank the sources so reviewers know what to trust first. A contemporaneous note is stronger than a later summary, and the client guideline is stronger than an internal assumption about what the client wants. Record the evidence type for each line so the analysis can separate a documentation gap from a genuine purpose gap. A task code without a note is the weakest source for a purpose question."]},{"heading":"Sampling","paragraphs":["Sample across timekeepers, task types, and clients so one matter does not define the result. Include entries that were paid without a question, because payment is not proof that the narrative was clear. Draw the sample before reading the narratives so the selection is not biased toward the disputed lines. If the population is small, review every line and extend the period.","Stratify the sample by entry length and by whether the client guideline requires a purpose statement. A short entry may pass more often because it is easier to read, while a long entry may hide the purpose in detail. Report the gap rate for each stratum rather than pooling them. The reader should be able to see where the standard breaks down."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code each line as clear purpose, activity only, generic wording, missing narrative, or unknown. Add a note for the task type and the stage of the matter. Keep the code list short enough that two reviewers can apply it consistently.","Have a second reviewer code a sample and compare the results. Resolve disagreements by returning to the narrative and the source note, not by majority vote. Report the agreement rate and revise any code that is applied inconsistently. If the reviewers cannot agree on what counts as a purpose, stop and fix the definition before continuing."]},{"heading":"Measuring the variable","paragraphs":["Measure the purpose gap rate by line, by billed value, and by task type. Report the median and the range for the narrative length so a few long entries are visible. Measure the share of lines that pass a blind reader test, where a reviewer who does not know the matter tries to state the purpose. Keep the raw counts with the analysis file.","Do not convert the gap to a dollar figure without an approved fee and collection data. The study measures narrative quality, not profitability. If the firm wants a revenue view, run it as a separate analysis with the finance owner. A precise dollar figure built on an incomplete narrative set is less useful than a clear line count."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall gap rate, the rate by task type, and the number of lines behind each figure. Show the share of billed value affected and the most common wording pattern. Compare only groups with similar client requirements and matter types. Include the lines that were clear so the report shows the full distribution.","Give the reader one table that answers the main question and put the coding detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["A missing note is not proof that no purpose existed, and a later summary is not proof that the purpose was clear at the time. Report the completeness of the evidence before drawing a conclusion. Small samples, changing client guidelines, and reviewer disagreement can all limit interpretation. A short entry may be perfectly clear to a reader who knows the matter.","Avoid comparing groups that differ in client sophistication or matter complexity. A client that reviews every line may receive fuller narratives than one that does not. Describe the context beside the rate and avoid ranking individual timekeepers. The purpose is to improve the record, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the narratives, source notes, and client guidelines in a controlled folder with access limited to the study team. Remove client names, matter details, and privileged content from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the specific matter. Keep privileged material in a separate restricted location.","Do not circulate a client-level or timekeeper-level list about narrative quality outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the billing system and to quoted entries. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common gap. If activity-only entries dominate, add a purpose prompt to the time-entry form with a short example. If long entries hide the purpose, add a review question at the prebill. If the guideline is unclear, ask the client for a sample of an acceptable narrative.","A lower gap rate is not the only useful outcome. Faster client approval and fewer questions can improve the process even when the rate stays similar. Report the direct result and the service result separately. Stop the change if it produces longer narratives without a clearer purpose."]},{"heading":"Review cadence","paragraphs":["Repeat the audit each quarter and after any change to the time-entry form, the client guideline, or the billing system. Keep the definitions and the unit stable so periods can be compared. Report the lines that were excluded or still open beside the main rate. Review the coding guide after the first repetition and keep the changes visible.","Review the result with the billing manager and the attorney who supervises the timekeepers, not only with the preparer. Ask which fix is easiest to sustain and which gap causes the most client questions. Set one change and a follow-up date, then check whether the change held. The next audit should test the repair, not just repeat the same count."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"U.S. Bureau of Labor Statistics","url":"https://www.bls.gov/"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"}],"publishedAt":"2026-11-11","thumbnail":"/thumbnails/november-11/how-often-do-billing-narratives-omit-the-business-purpose-of-the-task.webp"},{"slug":"what-share-of-trust-replenishment-requests-arrive-after-the-retainer-is-exhausted","title":"What share of trust replenishment requests arrive after the retainer is exhausted?","summary":"A timing study that measures how often a client is asked to replenish trust only after the balance has already fallen below the work in progress.","cluster":"Trust accounting","finding":"Late replenishment requests usually reflect a missing early-warning trigger rather than a client unwilling to pay, and the delay shifts risk onto the firm.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks what share of trust replenishment requests are sent after the retainer balance has already been exhausted. The unit is a replenishment event, and the measure is whether the request date precedes or follows the date the available trust balance reached zero. The study covers retainer-based matters that were active during the period. It does not evaluate whether the retainer amount was appropriate at the start.","Scope the study to matters with a written retainer agreement and a trust ledger that records both deposits and withdrawals. Include matters that received one request, several requests, and no request at all so the denominator reflects the full portfolio. Exclude matters with no trust activity and record the number excluded. State the trust system, the billing system, and the owner of the analysis."]},{"heading":"Defining the event","paragraphs":["Define a replenishment request as a written communication that asks the client to deposit additional funds into trust. The request date is the date it was sent, not the date it was drafted or discussed. Define exhaustion as the point when the available trust balance for the matter reaches zero after applying approved transfers. A request sent on the same day as exhaustion counts as late for this study.","Distinguish a scheduled replenishment from a reactive one. A scheduled request follows the retainer agreement, such as a monthly top-up, while a reactive request follows a balance alert or a refused transfer. Code the two separately because the process fix differs. A matter can have both types over its life, so code each event on its own."]},{"heading":"Population and denominator","paragraphs":["The population is every replenishment event on an included matter during the period. Report the number of matters, the number of events, the number excluded, and the number in the final sample. If a matter received several requests, count each one separately or state the rule used. Keep the unit stable across periods so the timing rate is comparable.","Report the share of requests sent before exhaustion, on the day of exhaustion, and after exhaustion. Also report the median number of days between exhaustion and the request. A single late request on a large matter can matter more than several on small matters, so report the trust amount beside the count. Report the trust balance at each request so the timing can be read beside the amount."]},{"heading":"Evidence sources","paragraphs":["Use the trust ledger, the retainer agreement, the client communication, and the billing system as the primary evidence. Compare the request date with the balance history and record the date each source was observed. If the ledger is incomplete, mark the event as unverified rather than estimating the balance. The evidence log should let a second reviewer repeat the timeline.","Rank the sources so reviewers know what to trust first. A contemporaneous trust ledger is stronger than a later reconciliation, and a sent message is stronger than a note that a call occurred. A retainer agreement is stronger than an internal assumption about the client's obligation. Record the evidence type for each event."]},{"heading":"Sampling","paragraphs":["Sample across clients, matter sizes, and relationship ages so one large client does not define the result. Include matters with a single retainer and matters with recurring replenishments. Draw the sample before reading the outcome so the selection is not biased toward the late cases. If the population is small, review every event and extend the period.","Stratify the sample by whether the matter had a documented balance alert or a scheduled review. A matter with a working alert should produce earlier requests than one without. Report the timing rate for each stratum rather than pooling them. The reader should be able to see whether the trigger or the client behavior explains the delay."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code each event as before exhaustion, same day, after exhaustion, or unknown, and record the trigger such as a scheduled review, a balance alert, a refused transfer, or a client request. Add the number of days late and the trust balance at the request date. Keep the code list short enough that two reviewers can apply it consistently.","Have a second reviewer code a sample and compare the results. Resolve disagreements by returning to the ledger and the sent message, not by majority vote. Report the agreement rate and revise any code that is applied inconsistently. If the reviewers cannot agree on the exhaustion date, stop and fix the definition before continuing."]},{"heading":"Measuring the variable","paragraphs":["Measure the share of late requests by event and by trust value. Report the median and the range for the days late so a few extreme cases are visible. Measure the time from the last approved transfer to the request, because that interval shows how quickly the balance was consumed. Keep the raw entries with the analysis file.","Do not convert the late days to a cost figure without an approved labor rate and a clear statement that it is an internal estimate. The study measures timing, not the cost of carrying the work. If the firm wants a cost view, run it separately with the finance owner. A precise number built on assumed rates is less useful than a clear distribution."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall late rate, the median days late, and the number of events behind each figure. Show the results by trigger type and by matter size. Compare only groups with similar retainer terms and billing cycles. Include the events that arrived early so the report shows the full distribution.","Give the reader one table that answers the main question and put the coding detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["A late request is not proof that the firm failed to notice the balance, and an early request is not proof that the process is healthy. Report the completeness of the ledger before drawing a conclusion. Small samples, manual transfers, and changing retainer terms can all limit interpretation. A client who pays slowly may receive a request earlier by design.","Avoid comparing matters that differ in write-off policy or trust activity. A matter with many small costs will consume trust differently from one with a single large fee. Describe the context beside the rate and avoid ranking individual billers. The purpose is to improve the trigger, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the trust ledgers, retainer agreements, and client messages in a controlled folder with access limited to the study team. Remove client names, balances, and matter details from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the amount. Keep the unredacted ledger in a separate restricted location.","Do not circulate a client-level list about late replenishment outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the trust system and to quoted messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common trigger. If the alert is missing, add a threshold notification at a set percentage of the retainer. If the review is manual, put a balance check on the weekly billing calendar. If the request is late because the invoice is late, fix the prebill timeline first.","A lower late rate is not the only useful outcome. Fewer refused transfers and a smoother client conversation can improve the relationship even when the rate stays similar. Report the direct result and the service result separately. Stop the change if it produces more alerts than the team can act on."]},{"heading":"Review cadence","paragraphs":["Repeat the study each quarter and after any change to the retainer terms, the trust system, or the billing calendar. Keep the definitions and the unit stable so periods can be compared. Report the events that were excluded or still open beside the main rate. Review the coding guide after the first repetition and keep the changes visible.","Review the result with the billing manager and the bookkeeper, not only with the preparer. Ask which fix is easiest to sustain and which delay creates the most client friction. Set one change and a follow-up date, then check whether the change held. The next study should test the repair, not just repeat the same count."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"U.S. Bureau of Labor Statistics","url":"https://www.bls.gov/"},{"label":"U.S. Small Business Administration","url":"https://www.sba.gov/"}],"publishedAt":"2026-11-11","thumbnail":"/thumbnails/november-11/what-share-of-trust-replenishment-requests-arrive-after-the-retainer-is-exhausted.webp"},{"slug":"how-much-close-time-is-lost-to-unresolved-timekeeper-edits","title":"How much close time is lost to unresolved timekeeper edits?","summary":"A time study that measures the review minutes spent waiting for, reconciling, and rechecking late timekeeper edits during the monthly close.","cluster":"Close cycle","finding":"Late edits rarely consume time when they are entered, but they consume review time repeatedly as the prebill, the totals, and the client summary are rebuilt around them.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how much close time is lost to unresolved timekeeper edits. The unit is a review minute attached to an edit, and the measure is the active time spent waiting, reconciling, and rechecking after the edit arrives. The study covers the close cycle from the time-entry cutoff to the released invoice. It does not evaluate whether the edit itself was justified.","Scope the study to closes with at least one edit received after the cutoff. Include edits that were accepted, rejected, and still open so the denominator reflects the full workload. Exclude closes with no late edits and record the number excluded. State the billing system, the close calendar, and the person who owns the time log."]},{"heading":"Defining the event","paragraphs":["Define a late edit as a change to time, narrative, rate, or matter allocation submitted after the published cutoff for the close. A correction made before the cutoff is part of normal work. A change requested by the client after the invoice is released belongs to the next cycle and a separate study. Write two examples and one boundary case before coding.","Distinguish an edit from a new entry. A new entry adds time that was not previously recorded, while an edit changes an existing record. The two have different causes and different fixes, so code them separately. A late entry may indicate a capture problem, while a late edit may indicate a review or approval problem."]},{"heading":"Population and denominator","paragraphs":["The population is every late edit received during an included close. Report the number of closes, the number of edits, the number excluded, and the number in the final sample. If one edit required several review passes, count the active minutes from each pass but keep the edit as one unit. State how rework was handled in the coding guide.","Report the minutes per edit and the share of close minutes spent on late edits. A high share can reflect one complex edit, so report the number of edits behind the share. Keep the raw time entries with the analysis file. The denominator should include the edits that were resolved quickly, not only the difficult ones."]},{"heading":"Evidence sources","paragraphs":["Use the billing system audit trail, the close calendar, the reviewer's time log, and the prebill versions as the primary evidence. Compare the edit timestamp with the cutoff and record the date each source was observed. If the time log is missing, mark the edit as incomplete rather than estimating from memory. The evidence log should let a second reviewer repeat the timeline.","Rank the sources so reviewers know what to trust first. A system audit trail is stronger than a later summary, and a contemporaneous time log is stronger than a recollection. A prebill version history is stronger than an assumption about what changed. Record the evidence type for each edit so the analysis can separate a documentation gap from a real delay."]},{"heading":"Sampling","paragraphs":["Sample across close cycles, matter types, and timekeepers so one difficult close does not define the result. Include edits that were resolved on the same day, because the quick cases are part of the baseline. Draw the sample before reading the outcome so the selection is not biased toward the disruptive edits. If the population is small, review every edit and extend the period.","Stratify the sample by whether the edit was requested by the timekeeper, the reviewer, or the client. Each source has a different approval path and a different delay pattern. Report the minutes per edit for each stratum rather than pooling them. The reader should be able to see where the close time actually goes."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code each edit as narrative, time value, rate, matter allocation, or other, and record the stage where it was found. Add the number of review passes and the person who requested the change. Code the outcome as accepted, rejected, or open so the time can be interpreted.","Have a second reviewer code a sample and compare the results. Resolve disagreements by returning to the audit trail and the prebill versions, not by majority vote. Report the agreement rate and revise any code that is applied inconsistently. If the reviewers cannot agree on what counts as an edit, stop and fix the definition before continuing."]},{"heading":"Measuring the variable","paragraphs":["Measure active review minutes with a short log completed at the moment of the work. Separate the time spent waiting, searching, reconciling, and communicating so the largest component is visible. Report the median and the range rather than a single average, because one difficult edit can dominate a mean. Keep the raw entries with the analysis file.","Do not convert the minutes to a dollar figure without an approved labor rate and a clear statement that it is an internal estimate. The study measures effort, not price. If the firm wants a cost view, run it separately with the finance owner. A precise number built on rounded guesses is less useful than a range with a clear source."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall minutes per edit, the share of close minutes affected, and the number of closes behind each figure. Show the median and range for each edit type and the most common stage where the edit was found. Compare only closes with similar volumes and review steps. Include the quick edits so the report shows the full distribution.","Give the reader one table that answers the main question and put the coding detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["Self-reported time can be rounded, and a missing log is not proof that no delay occurred. Report the completeness of the time evidence before drawing a conclusion. Small samples, changing close calendars, and reviewer disagreement can all limit interpretation. An edit that was resolved quickly may still have interrupted a review that had to restart.","Avoid comparing closes that differ in volume or client requirements. A close with many small matters will produce a different pattern from one with a single large submission. Describe the context beside the minutes and avoid ranking individual reviewers. The purpose is to improve the cutoff and the queue, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the audit trails, close calendars, and time logs in a controlled folder with access limited to the study team. Remove timekeeper names, client details, and specific amounts from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the matter. Keep the unredacted evidence separate from the working analysis.","Do not circulate a person-level or client-level list about late edits outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the billing system and to quoted messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common edit. If narrative edits dominate, improve the entry guidance and the first review. If time-value edits dominate, add a daily time check before the cutoff. If rate edits dominate, fix the matter setup. Test one change on one close before applying it broadly.","A lower minutes-per-edit figure is not the only useful outcome. A calmer close and fewer rechecks can improve the team even when the minutes stay similar. Report the direct result and the service result separately. Stop the change if it pushes the edit into a private channel where it cannot be reviewed."]},{"heading":"Review cadence","paragraphs":["Repeat the study each close cycle and after any change to the cutoff, the billing system, or the review steps. Keep the definitions and the unit stable so periods can be compared. Report the edits that were excluded or still open beside the main measure. Review the coding guide after the first repetition and keep the changes visible.","Review the result with the billing manager and the timekeepers, not only with the reviewer. Ask which fix is easiest to sustain and which edit creates the most rework. Set one change and a follow-up date, then check whether the change held. The next study should test the repair, not just repeat the same count."]}],"sources":[{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"U.S. Bureau of Labor Statistics","url":"https://www.bls.gov/"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"NIST Cybersecurity Framework 2.0","url":"https://www.nist.gov/cyberframework"}],"publishedAt":"2026-11-11","thumbnail":"/thumbnails/november-11/how-much-close-time-is-lost-to-unresolved-timekeeper-edits.webp"},{"slug":"how-consistent-are-write-down-approval-limits-across-billing-managers","title":"How consistent are write-down approval limits across billing managers?","summary":"A control study that compares the written authority, the applied approval level, and the recorded reason for adjustments of the same size.","cluster":"Write-offs","finding":"Inconsistent approval is less often a missing policy than a policy that is interpreted differently by each manager, which makes the same adjustment routine in one book and an exception in another.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how consistently write-down approval limits are applied across billing managers. The unit is an approved adjustment, and the measure is whether the approver's authority, the recorded reason, and the supporting evidence match the written policy for that amount. The study covers adjustments on invoices issued during the period. It does not evaluate whether the adjustment was commercially wise.","Scope the study to billing managers who approved at least one adjustment during the period and to adjustments above the firm's documentation threshold. Include adjustments that were later reversed or corrected so the denominator reflects real decisions. Exclude adjustments below the threshold and record the number excluded. State the policy version, the approval system, and the owner of the analysis."]},{"heading":"Defining the event","paragraphs":["Define an adjustment as any reduction to a billed amount, including a write-down, a write-off, a courtesy credit, and an error correction. The approval limit is the maximum amount a named role may approve without escalation. The applied approver is the person whose name appears on the approval record. A verbal approval that was never recorded counts as undocumented for this study.","Distinguish a split adjustment from a single adjustment. Splitting a large reduction into smaller entries to stay inside a limit is a control failure, not a series of routine decisions. Code the split separately and record the total amount. A legitimate partial credit on separate invoices should not be coded as a split when the client requested it that way."]},{"heading":"Population and denominator","paragraphs":["The population is every adjustment above the documentation threshold on an included invoice. Report the number of managers, the number of adjustments, the number excluded, and the number in the final sample. If one invoice received several adjustments, count each one separately or state the rule used. Keep the unit stable across periods so the consistency rate is comparable.","Report the share of adjustments approved inside the limit, above the limit with an escalation, above the limit without an escalation, and with no recorded approver. Also report the median amount by manager group. A high share inside the limit can still hide a split, so report the count of split cases beside the rate. Report the share of adjustments with a completed evidence package as a separate measure."]},{"heading":"Evidence sources","paragraphs":["Use the approval record, the delegation schedule, the invoice history, and the client correspondence as the primary evidence. Compare the approver and the amount with the limit in force on the approval date. Record the date each source was observed and the policy version. If the approval record is missing, mark the adjustment as undocumented rather than inferring authority from the title.","Rank the sources so reviewers know what to trust first. A signed approval record is stronger than an email, and a dated delegation schedule is stronger than a current org chart. A client request is stronger than an internal assumption about why the adjustment was made. Record the evidence type for each adjustment."]},{"heading":"Sampling","paragraphs":["Sample across managers, offices, and adjustment sizes so one large credit does not define the result. Include adjustments near the limit, because that is where interpretation differs most. Draw the sample before reading the outcome so the selection is not biased toward the suspicious cases. If the population is small, review every adjustment and extend the period.","Stratify the sample by whether the adjustment was a courtesy credit or an error correction. A courtesy credit may follow a different approval path from a correction. Report the consistency rate for each stratum rather than pooling them. The reader should be able to see whether the policy or the practice explains the difference."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code each adjustment as inside limit, escalated, not escalated, split, or undocumented, and record the reason category. Add the approver role, the amount, and the policy version. Keep the code list short enough that two reviewers can apply it consistently.","Have a second reviewer code a sample and compare the results. Resolve disagreements by returning to the delegation schedule and the approval record, not by majority vote. Report the agreement rate and revise any code that is applied inconsistently. If the reviewers cannot agree on which policy version applied, stop and fix the timeline before continuing."]},{"heading":"Measuring the variable","paragraphs":["Measure the consistency rate by adjustment and by manager group. Report the median and the range for the adjustment amount so a few large cases are visible. Measure the share of adjustments with a complete reason and evidence package. Keep the raw counts with the analysis file so a reviewer can check the calculation.","Do not convert the adjustments to a realization figure without the approved fee and collection data. The study measures approval consistency, not profitability. If the firm wants a realization view, run it as a separate analysis with the finance owner. A precise percentage built on incomplete records is less useful than a clear exception count."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall consistency rate, the exception count by type, and the number of adjustments behind each figure. Show the results by manager group and by adjustment size. Compare only groups with the same policy version and approval system. Include the adjustments that followed the policy so the report shows the full distribution.","Give the reader one table that answers the main question and put the coding detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["A missing approval record is not proof that no approval occurred, and a recorded approval is not proof that the authority was valid. Report the completeness of the evidence before drawing a conclusion. Small samples, mid-period policy changes, and reviewer disagreement can all limit interpretation. A manager who inherited a decision may appear inconsistent through no fault of their own.","Avoid comparing managers who handle different client relationships or matter types. A manager with many long-standing clients may see more courtesy adjustments than one with new clients. Describe the context beside the rate and avoid ranking individual managers. The purpose is to clarify the policy, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the approval records, delegation schedules, and invoice histories in a controlled folder with access limited to the study team. Remove manager names, client names, and specific amounts from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the amount. Keep the unredacted evidence separate from the working analysis.","Do not circulate a manager-level list about approval consistency outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the approval system and to quoted messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common exception. If the limit is unclear, rewrite it with examples at the boundary. If splits dominate, add a check for multiple adjustments on the same invoice. If the approval record is missing, make the field required before the invoice can be released. Test the change on one manager group.","A higher consistency rate is not the only useful outcome. Faster approvals and clearer client conversations can improve the process even when the rate stays similar. Report the direct result and the service result separately. Stop the change if it adds a step that the team works around instead of using."]},{"heading":"Review cadence","paragraphs":["Repeat the study each quarter and after any change to the delegation schedule or the approval system. Keep the definitions and the unit stable so periods can be compared. Report the adjustments that were excluded or still open beside the main rate. Review the coding guide after the first repetition and keep the changes visible.","Review the result with the billing manager and the finance owner, not only with the approvers. Ask which fix is easiest to sustain and which exception creates the most rework. Set one change and a follow-up date, then check whether the change held. The next study should test the repair, not just repeat the same count."]}],"sources":[{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"U.S. Bureau of Labor Statistics","url":"https://www.bls.gov/"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-11","thumbnail":"/thumbnails/november-11/how-consistent-are-write-down-approval-limits-across-billing-managers.webp"},{"slug":"what-share-of-new-matters-lack-a-client-billing-guideline-record","title":"What share of new matters lack a client billing guideline record?","summary":"An intake audit that checks whether a new matter has a current guideline source, an owner, and a review question before the first time entry.","cluster":"Billing guidelines","finding":"A missing guideline record at intake is usually invisible until the first invoice is rejected, which turns a simple setup step into a client dispute.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks what share of new matters lack a client billing guideline record at intake. The unit is a newly opened matter, and the measure is whether the matter record contains a current guideline source, a named owner, and at least one review question before the first time entry. The study covers matters opened during the period. It does not evaluate the quality of the legal work.","Scope the study to matters with an engagement letter and a client that has issued written billing guidelines. Include matters opened through every intake channel so the denominator reflects the full workload. Exclude matters with no written guideline and record the number excluded. State the matter system, the guideline repository, and the owner of the analysis."]},{"heading":"Defining the event","paragraphs":["Define a complete guideline record as one that links the current client source, names the owner, and lists the review questions the billing team will use. A note that says guidelines apply is not complete. A record with an outdated source is incomplete for this study. Write two examples and one boundary case before coding.","Distinguish a missing record from a late record. A record created after the first time entry is late even if it is complete. A late record can still be useful, but it did not prevent the intake gap. Code the two separately because the process fix differs."]},{"heading":"Population and denominator","paragraphs":["The population is every new matter opened during the period that meets the inclusion rule. Report the number of matters, the number excluded, and the number in the final sample. Count matters rather than clients, because one client can open several matters with different rules. Keep the unit stable across periods so the completeness rate is comparable.","Report the completeness rate by matter and by required element. A matter can have a source but no owner, or an owner but no review question. Report the element-level rate beside the overall rate. The element measure should count only the elements required at intake."]},{"heading":"Evidence sources","paragraphs":["Use the matter record, the guideline repository, the engagement letter, and the intake checklist as the primary evidence. Compare the source date with the matter open date and record the date each source was observed. If the guideline is stored only in an email, mark the record as incomplete for this study. The evidence log should let a second reviewer repeat the match.","Rank the sources so reviewers know what to trust first. A current repository entry is stronger than an email attachment, and a dated intake checklist is stronger than a later note. A client portal link is stronger than an internal summary of the guideline. Record the evidence type for each matter so the analysis can separate a storage problem from a process gap."]},{"heading":"Sampling","paragraphs":["Sample across practice groups, offices, and intake channels so one team does not define the result. Include matters opened by a partner, by an assistant, and through a client portal. Draw the sample before reading the outcome so the selection is not biased toward the well-documented matters. If the population is small, review every matter and extend the period.","Stratify the sample by whether the client had an existing guideline on file from a prior matter. A returning client may receive a faster setup because the source is already known. Report the completeness rate for each stratum rather than pooling them. The reader should be able to see whether the gap is concentrated in new clients."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code each matter as complete, source missing, owner missing, questions missing, outdated, or late. Add the intake channel and the matter type. Keep the code list short enough that two reviewers can apply it consistently.","Have a second reviewer code a sample and compare the results. Resolve disagreements by returning to the matter record and the repository, not by majority vote. Report the agreement rate and revise any code that is applied inconsistently. If the reviewers cannot agree on what counts as current, stop and fix the definition before continuing."]},{"heading":"Measuring the variable","paragraphs":["Measure the completeness rate by matter, by element, and by intake channel. Report the median and the range for the days between matter open and record creation. Measure the share of matters that received a review question before the first time entry. Keep the raw counts with the analysis file so a reviewer can check the calculation.","Do not convert the gap to a dollar figure without the invoice and adjustment data. The study measures intake completeness, not cost. If the firm wants a cost view, run it separately with the finance owner. A precise number built on incomplete matter records is less useful than a clear element-level count."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall completeness rate, the element-level gaps, and the number of matters behind each figure. Show the results by intake channel and by client type. Compare only groups with similar guideline requirements. Include the matters that were complete so the report shows the full distribution.","Give the reader one table that answers the main question and put the coding detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["A missing record is not proof that the guideline was unavailable, and a complete record is not proof that the team read it. Report the completeness of the intake evidence before drawing a conclusion. Small samples, concurrent system changes, and reviewer disagreement can all limit interpretation. A matter opened during a system migration may have a record in a legacy location.","Avoid comparing matters that differ in client sophistication or urgency. An emergency matter may be opened before the guideline is filed, with the record completed later. Describe the context beside the rate and avoid ranking individual assistants. The purpose is to improve intake, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the matter records, guidelines, and intake checklists in a controlled folder with access limited to the study team. Remove client names, matter details, and specific rates from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the matter. Keep privileged material in a separate restricted location.","Do not circulate a client-level or assistant-level list about guideline completeness outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the matter system and to quoted messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common gap. If the source is missing, make the guideline link a required intake field. If the owner is missing, assign it automatically by practice group. If the questions are missing, generate them from the client's template. Test the change on one intake channel before applying it broadly.","A higher completeness rate is not the only useful outcome. Faster first invoices and fewer rejections can improve the process even when the rate stays similar. Report the direct result and the service result separately. Stop the change if it becomes a field that the team fills in after the matter is open."]},{"heading":"Review cadence","paragraphs":["Repeat the audit each quarter and after any change to the intake system, the guideline repository, or the client mix. Keep the definitions and the unit stable so periods can be compared. Report the matters that were excluded or still open beside the main rate. Review the coding guide after the first repetition and keep the changes visible.","Review the result with the billing manager and the intake team, not only with the preparer. Ask which fix is easiest to sustain and which gap causes the most rework. Set one change and a follow-up date, then check whether the change held. The next audit should test the repair, not just repeat the same count."]}],"sources":[{"label":"American Bar Association Model Rules of Professional Conduct","url":"https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"U.S. Small Business Administration","url":"https://www.sba.gov/"},{"label":"U.S. Bureau of Labor Statistics","url":"https://www.bls.gov/"},{"label":"U.S. Census Bureau","url":"https://www.census.gov/"}],"publishedAt":"2026-11-11","thumbnail":"/thumbnails/november-11/what-share-of-new-matters-lack-a-client-billing-guideline-record.webp"},{"slug":"how-often-do-accrual-estimates-differ-from-the-next-invoice","title":"How often do accrual estimates differ from the next invoice?","summary":"A reconciliation study that compares each quarterly accrual estimate with the invoice that followed and classifies the causes of material variance.","cluster":"Accruals","finding":"Accrual variance is often treated as a forecasting problem, but much of it comes from unbilled time that was held, written down, or never entered before the cutoff.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how often a quarterly accrual estimate differs from the invoice that follows it. The unit is a matter-level accrual line, and the measure is the absolute difference between the estimate and the invoiced amount. The study covers accruals delivered to corporate clients during the period. It does not evaluate whether the client's accounting treatment was correct.","Scope the study to matters with an accrual estimate and an invoice issued within the following two quarters. Include matters that were invoiced in full, in part, and not at all so the denominator reflects the full portfolio. Exclude matters with no accrual line and record the number excluded. State the accrual definition, the billing system, and the owner of the analysis."]},{"heading":"Defining the event","paragraphs":["Define a material variance as a difference above a threshold agreed with the client, such as a percentage of the estimate or a fixed amount. A variance below the threshold is still recorded but grouped separately. The estimate date is the date the packet was delivered, not the date the work was prepared. A later revision creates a new estimate and a separate comparison.","Distinguish a timing variance from a value variance. A timing variance occurs when the work is invoiced in a later quarter than estimated, while a value variance occurs when the invoiced amount itself differs. Keep the two categories separate because the client response differs. A timing variance may need only an explanation, while a value variance may need a process change."]},{"heading":"Population and denominator","paragraphs":["The population is every matter-level accrual line in a delivered packet that meets the inclusion rule. Report the number of packets, the number of lines, the number excluded, and the number in the final sample. Count lines rather than packets, because one packet can contain many matters. Keep the unit stable across quarters so the variance rate is comparable.","Report the share of lines with any variance and the share with a material variance. Also report the median absolute difference and the total signed difference so offsetting errors are visible. A high variance rate with a small total difference may be less concerning than the reverse, so report both. The signed difference shows whether the firm tends to estimate high or low across the portfolio."]},{"heading":"Evidence sources","paragraphs":["Use the delivered accrual packet, the invoice, the time and cost detail, and the client's confirmation as the primary evidence. Compare the estimate line with the invoice line and record the date each was observed. If the invoice was revised, use the final version and note the revision date. The evidence log should let a second reviewer repeat the comparison.","Rank the sources so reviewers know what to trust first. A delivered packet is stronger than a draft, and a final invoice is stronger than a pro forma. A client confirmation is stronger than an internal assumption about what was accepted. Record the evidence type for each line so the analysis can separate a communication gap from a calculation error."]},{"heading":"Sampling","paragraphs":["Sample across clients, matter sizes, and quarters so one large matter does not define the result. Include lines that were estimated accurately, because the clean cases are part of the distribution. Draw the sample before reading the invoice so the selection is not biased toward the variances. If the population is small, review every line and extend the period.","Stratify the sample by whether the matter had unbilled time held for review at the cutoff. A matter with held time may show a larger timing variance than one with a clean cutoff. Report the variance rate for each stratum rather than pooling them. The reader should be able to see whether the estimate or the cutoff explains the difference."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code each variance as timing, rate change, scope change, held time, write-down, cost estimate, or unknown. Add the amount and the quarter. Keep the code list short enough that two reviewers can apply it consistently.","Have a second reviewer code a sample and compare the results. Resolve disagreements by returning to the packet and the invoice, not by majority vote. Report the agreement rate and revise any code that is applied inconsistently. If the reviewers cannot agree on the primary cause, stop and fix the definitions before continuing."]},{"heading":"Measuring the variable","paragraphs":["Measure the absolute variance, the signed variance, and the variance as a share of the estimate. Report the median and the range so a few large matters are visible. Measure the time between the estimate date and the invoice date, because a long gap increases the chance of a timing difference. Keep the raw entries with the analysis file.","Do not convert the variance to a revenue or profitability figure without the approved fee and collection data. The study measures estimate accuracy, not financial performance. If the firm wants a revenue view, run it separately with the finance owner. A precise number built on an estimated rate is less useful than a clear variance distribution."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall variance rate, the material variance rate, and the median absolute difference. Show the results by cause and by client. Compare only groups with similar accrual definitions and cutoff rules. Include the lines that matched so the report shows the full distribution.","Give the reader one table that answers the main question and put the coding detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["A variance is not proof that the estimate was careless, and a match is not proof that the method is sound. Report the completeness of the packet and invoice evidence before drawing a conclusion. Small samples, changing scopes, and reviewer disagreement can all limit interpretation. A single large matter can move the total even when most lines are accurate.","Avoid comparing clients that use different accrual definitions or billing cycles. A client with a fiscal quarter that differs from the calendar quarter will produce a different timing pattern. Describe the context beside the rate and avoid ranking individual preparers. The purpose is to improve the estimate, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the accrual packets, invoices, and client confirmations in a controlled folder with access limited to the study team. Remove client names, amounts, and matter details from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the amount. Keep the unredacted evidence separate from the working analysis.","Do not circulate a client-level or preparer-level list about accrual variance outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the packet and to quoted messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common cause. If held time dominates, separate held work from the estimate and explain it in the packet. If rate changes dominate, confirm the approved rate before the cutoff. If costs dominate, add a vendor estimate check. Test one change on the next quarter before applying it broadly.","A lower variance rate is not the only useful outcome. A clearer packet and fewer client questions can improve the relationship even when the rate stays similar. Report the direct result and the service result separately. Stop the change if it makes the packet longer without improving the estimate."]},{"heading":"Review cadence","paragraphs":["Repeat the study each quarter and after any change to the accrual definition, the billing system, or the client mix. Keep the definitions and the unit stable so periods can be compared. Report the lines that were excluded or still open beside the main rate. Review the coding guide after the first repetition and keep the changes visible.","Review the result with the billing manager and the client relationship owner, not only with the preparer. Ask which fix is easiest to sustain and which cause creates the most client questions. Set one change and a follow-up date, then check whether the change held. The next study should test the repair, not just repeat the same count."]}],"sources":[{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"U.S. Bureau of Labor Statistics","url":"https://www.bls.gov/"},{"label":"U.S. Census Bureau","url":"https://www.census.gov/"},{"label":"U.S. Small Business Administration","url":"https://www.sba.gov/"}],"publishedAt":"2026-11-11","thumbnail":"/thumbnails/november-11/how-often-do-accrual-estimates-differ-from-the-next-invoice.webp"},{"slug":"how-much-invoice-review-time-goes-to-missing-matter-references","title":"How much invoice review time goes to missing matter references?","summary":"A time study that measures the review minutes spent tracing cost and time lines that lack a usable matter reference.","cluster":"Invoice quality","finding":"A missing matter reference looks like a small data defect, but it pushes a line out of the normal review path and into manual tracing that is rarely counted.","sections":[{"heading":"Question and scope","paragraphs":["This protocol asks how much invoice review time goes to lines that lack a usable matter reference. The unit is a review minute attached to a line, and the measure is the active time spent searching for the matter, confirming the allocation, and correcting the record. The study covers the invoice review stage before release. It does not evaluate the quality of the underlying legal work.","Scope the study to invoices with at least one time or cost line reviewed during the period. Include invoices that were released, held, and adjusted so the denominator reflects the full workload. Exclude invoices with no lines and record the number excluded. State the billing system, the matter master, and the owner of the time log."]},{"heading":"Defining the event","paragraphs":["Define a missing reference as a line that cannot be matched to a matter using the reference on the invoice, the client matter number, or the timekeeper's default matter. A line with a reference that is merely formatted differently is a formatting issue, not a missing reference. A line with a valid matter but the wrong client number is an allocation issue. Write two examples and one boundary case before coding.","Distinguish a missing reference from an ambiguous one. A missing reference has no usable identifier, while an ambiguous reference points to more than one matter. The repair differs, so code the two separately. A line that is later matched after a search is still a missing-reference event for the time study."]},{"heading":"Population and denominator","paragraphs":["The population is every reviewed line on an included invoice. Report the number of invoices, the number of lines, the number excluded, and the number in the final sample. If a line was reviewed more than once, count the active minutes from each pass but keep the line as one unit. State how rework was handled in the coding guide.","Report the review minutes per line and the share of minutes spent on missing-reference lines. A high share can reflect a few complex invoices, so report the number of invoices behind the share. Keep the raw time entries with the analysis file. The denominator should include the lines that were cleared quickly, not only the problem cases."]},{"heading":"Evidence sources","paragraphs":["Use the invoice, the matter master, the time and cost detail, and the reviewer's time log as the primary evidence. Compare the line reference with the matter master and record the date each was observed. If the time log is missing, mark the line as incomplete rather than estimating from memory. The evidence log should let a second reviewer repeat the match.","Rank the sources so reviewers know what to trust first. A contemporaneous time log is stronger than a later estimate, and the matter master is stronger than a billing note. A client matter number is stronger than an internal shorthand. Record the evidence type for each line so the analysis can separate a data gap from a real review burden."]},{"heading":"Sampling","paragraphs":["Sample across clients, matter types, and invoice sizes so one large invoice does not define the result. Include lines that were clear, because the review time for a clean line is part of the baseline. Draw the sample before reading the outcome so the selection is not biased toward the difficult cases. If the population is small, review every line and extend the period.","Stratify the sample by whether the line came from a time entry or a cost entry. Cost lines may lack a matter reference more often because they originate with a vendor. Report the minutes per line for each stratum rather than pooling them. The reader should be able to see where the review burden actually sits."]},{"heading":"Coding the record","paragraphs":["Use a short code list that points to a specific repair. Code each line as clear, missing reference, ambiguous reference, wrong client number, or other, and record the stage where the issue was found. Add the number of search steps and the outcome. Code the line as cleared, corrected, or escalated so the time can be interpreted.","Have a second reviewer code a sample and compare the results. Resolve disagreements by returning to the matter master and the invoice, not by majority vote. Report the agreement rate and revise any code that is applied inconsistently. If the reviewers cannot agree on what counts as usable, stop and fix the definition before continuing."]},{"heading":"Measuring the variable","paragraphs":["Measure active review minutes with a short log completed at the moment of the work. Separate the time spent searching, confirming, correcting, and communicating so the largest component is visible. Report the median and the range rather than a single average, because one complex invoice can dominate a mean. Keep the raw entries with the analysis file.","Do not convert the minutes to a dollar figure without an approved labor rate and a clear statement that it is an internal estimate. The study measures effort, not price. If the firm wants a cost view, run it separately with the finance owner. A precise number built on rounded guesses is less useful than a range with a clear source."]},{"heading":"Analysis and reporting","paragraphs":["Report the overall minutes per line, the share spent on missing-reference lines, and the number of invoices behind each figure. Show the median and range for each issue type and the most common stage where the issue was found. Compare only groups with similar client and matter mixes. Include the clean lines so the report shows the full distribution.","Give the reader one table that answers the main question and put the coding detail in an appendix. Write the finding in plain language before presenting the technical definition. Include the cases that contradict the pattern rather than hiding them in an average. A report that cannot be acted on is just another record of the past."]},{"heading":"Limits and sources of error","paragraphs":["Self-reported time can be rounded, and a missing log is not proof that no review occurred. Report the completeness of the time evidence before drawing a conclusion. Small samples, changing matter structures, and reviewer disagreement can all limit interpretation. A line that was cleared quickly may still have required a search that the reviewer did not log.","Avoid comparing invoices that differ in cost volume or client requirements. A matter with many vendor costs will produce a different pattern from one with a single fee. Describe the context beside the minutes and avoid ranking individual reviewers. The purpose is to improve the intake and the matter master, not to judge professional worth."]},{"heading":"Privacy and retention","paragraphs":["Store the invoices, matter master, and time logs in a controlled folder with access limited to the study team. Remove client names, amounts, and matter details from the analysis file when they are not needed. If an example is shared, use a role label and redact the client and the matter. Keep the unredacted evidence separate from the working analysis.","Do not circulate a reviewer-level or client-level list about review time outside the management context. Aggregate the results before sharing them more broadly, and check that a small group cannot be re-identified. The same rule applies to screenshots of the billing system and to quoted vendor messages. Privacy is part of the method, not an afterthought added at the end."]},{"heading":"Applying the result","paragraphs":["Choose one change that matches the most common issue. If the matter master is incomplete, add a required reference before a line can be posted. If vendor costs lack a reference, require the matter number on the purchase order. If the client number is wrong, fix the mapping at intake. Test the change on one client before applying it broadly.","A lower minutes-per-line figure is not the only useful outcome. Fewer client questions and a cleaner matter master can improve the process even when the minutes stay similar. Report the direct result and the service result separately. Stop the change if it pushes the check into a private channel where it cannot be reviewed."]},{"heading":"Review cadence","paragraphs":["Repeat the study each invoice cycle and after any change to the matter master, the cost intake, or the billing system. Keep the definitions and the unit stable so periods can be compared. Report the lines that were excluded or still open beside the main measure. Review the coding guide after the first repetition and keep the changes visible.","Review the result with the billing manager and the matter master owner, not only with the reviewer. Ask which fix is easiest to sustain and which issue creates the most rework. Set one change and a follow-up date, then check whether the change held. The next study should test the repair, not just repeat the same count."]}],"sources":[{"label":"Legal Electronic Data Exchange Standard","url":"https://ledes.org/"},{"label":"U.S. Government Accountability Office Green Book","url":"https://www.gao.gov/products/gao-14-704g"},{"label":"Internal Revenue Service recordkeeping guidance","url":"https://www.irs.gov/businesses/small-businesses-self-employed/what-kind-of-records-should-i-keep"},{"label":"Federal Trade Commission data security guidance","url":"https://www.ftc.gov/business-guidance/privacy-security/data-security"},{"label":"U.S. Bureau of Labor Statistics","url":"https://www.bls.gov/"},{"label":"United States Department of Labor work hours guidance","url":"https://www.dol.gov/general/topic/workhours"}],"publishedAt":"2026-11-11","thumbnail":"/thumbnails/november-11/how-much-invoice-review-time-goes-to-missing-matter-references.webp"}];
